window.GEN.loot = {"oggetti": [{"roll": 1, "name": "Sacco a Pelo di Qualità", "en": "Premium Bedroll", "text": "Durante gli interludi, rimuovete automaticamente uno Stress."}, {"roll": 2, "name": "Fischietto del Musico", "en": "Piper Whistle", "text": "Questo fischietto fatto a mano ha un suono inconfondibile. Quando ci soffiate dentro, il suo suono acuto si sente nel raggio di un miglio."}, {"roll": 3, "name": "Faretra Incantata", "en": "Charging Quiver", "text": "Quando superate un attacco con una freccia custodita in questa faretra, ottenete un bonus al tiro danni pari al vostro rango attuale."}, {"roll": 4, "name": "Torcia di Alistair", "en": "Alistair's Torch", "text": "Potete accendere questa torcia magica a volontà. La sua luce riempie uno spazio molto più ampio del normale, abbastanza da illuminare una caverna a giorno."}, {"roll": 5, "name": "Globi Parlanti", "en": "Speaking Orbs", "text": "Questa coppia di globi permette a chi li tiene di comunicare tra loro a qualunque distanza."}, {"roll": 6, "name": "Manette", "en": "Manacles", "text": "Questo paio di ceppi con serratura è dotato di chiave."}, {"roll": 7, "name": "Mantello Arcano", "en": "Arcane Cloak", "text": "Una creatura con un tratto da Incantatore che indossa questo mantello può modificarne colore, consistenza e dimensioni a volontà."}, {"roll": 8, "name": "Rete Intrecciata", "en": "Woven Net", "text": "Potete effettuare un Tiro Astuzia usando questa rete per intrappolare una creatura piccola. Un bersaglio intrappolato può liberarsi superando un tiro attacco (16)."}, {"roll": 9, "name": "Otre di Fuoco", "en": "Fire Jar", "text": "Potete versare lo strano liquido contenuto in questo otre per produrre fuoco all'istante. Il contenuto si rigenera quando effettuate un riposo lungo."}, {"roll": 10, "name": "Verga Levitante", "en": "Suspended Rod", "text": "Questa verga piatta è incisa di rune. Quando la attivate, resta immediatamente sospesa a mezz'aria. Finché non viene disattivata, non può muoversi, ignora la gravità e rimane ferma dov'è."}, {"roll": 11, "name": "Gemma delle Apparenze", "en": "Glamour Stone", "text": "Attivate questa gemma, grande quanto un sassolino, per memorizzare l'aspetto di qualcuno che potete vedere. Spendete una Speranza per ricreare magicamente su di voi quell'aspetto sotto forma di illusione."}, {"roll": 12, "name": "Scrigno Vuoto", "en": "Empty Chest", "text": "Questo scrigno magico sembra vuoto. Quando pronunciate una parola o compiete un gesto prestabilito e lo aprite, potete vedere gli oggetti custoditi al suo interno."}, {"roll": 13, "name": "Trasportino del Famiglio", "en": "Companion Case", "text": "Questo trasportino può contenere un piccolo compagno animale. Finché il compagno è al suo interno, l'animale e il trasportino sono immuni a tutti i danni e agli effetti dannosi."}, {"roll": 14, "name": "Frecce Trapassanti", "en": "Piercing Arrows", "text": "Tre volte per riposo, quando superate un attacco con una di queste frecce, potete aggiungere la vostra Competenza al tiro danni."}, {"roll": 15, "name": "Pietra del Valore", "en": "Valorstone", "text": "Potete incastonare questa pietra in un'armatura che non abbia già una caratteristica. L'armatura ottiene la seguente caratteristica. Resiliente: prima di marcare la vostra ultima Casella Armatura, tirate un d6. Con un risultato di 6, riducete la gravità del danno di una soglia senza marcare una Casella Armatura."}, {"roll": 16, "name": "Passepartout", "en": "Skeleton Key", "text": "Quando usate questa chiave per aprire una porta chiusa a chiave, ottenete vantaggio al Tiro Astuzia."}, {"roll": 17, "name": "Prisma Arcano", "en": "Arcane Prism", "text": "Collocate questo prisma in un punto a vostra scelta e attivatelo. Tutti gli alleati entro distanza Ravvicinata dal prisma ottengono un bonus di +1 ai loro Tiri Incantesimo. Finché è attivo, il prisma non può essere spostato. Una volta disattivato, non può essere riattivato fino al vostro prossimo riposo lungo."}, {"roll": 18, "name": "Ricetta della Pozione di Recupero Minore", "en": "Minor Stamina Potion Recipe", "text": "Come mossa da interludio, potete usare l'osso di una creatura per preparare una Pozione di Recupero Minore."}, {"roll": 19, "name": "Ricetta della Pozione di Guarigione Minore", "en": "Minor Health Potion Recipe", "text": "Come mossa da interludio, potete usare una fiala di sangue per preparare una Pozione di Guarigione Minore."}, {"roll": 20, "name": "Bussola del Ritorno", "en": "Homing Compasses", "text": "Queste due bussole puntano l'una verso l'altra, per quanto lontane siano."}, {"roll": 21, "name": "Spiritello Suggeritore", "en": "Corrector Sprite", "text": "Questo minuscolo spiritello si accomoda nella curva del vostro condotto uditivo e vi sussurra consigli utili durante il combattimento. Una volta per riposo breve, potete ottenere vantaggio a un tiro attacco."}, {"roll": 22, "name": "Guanti del Geco", "en": "Gecko Gloves", "text": "Potete arrampicarvi su superfici verticali e muovervi sui soffitti."}, {"roll": 23, "name": "Diario dei Segreti", "en": "Lorekeeper", "text": "Potete annotare in questo libro il nome e i dettagli di un massimo di tre creature ostili. Ottenete un bonus di +1 ai tiri azione contro quelle creature."}, {"roll": 24, "name": "Ricetta di Nerofumo", "en": "Vial of Darksmoke Recipe", "text": "Come mossa da interludio, potete marcare uno Stress per preparare una Fiala di Nerofumo."}, {"roll": 25, "name": "Pietra del Sangue", "en": "Bloodstone", "text": "Potete incastonare questa pietra in un'arma che non abbia già una caratteristica. L'arma ottiene la seguente caratteristica. Brutale: quando ottenete il valore massimo su un dado danni, tirate un dado danni aggiuntivo."}, {"roll": 26, "name": "Gemma della Grandezza", "en": "Greatstone", "text": "Potete incastonare questa pietra in un'arma che non abbia già una caratteristica. L'arma ottiene la seguente caratteristica. Potente: con un attacco riuscito, tirate un dado danni aggiuntivo e scartate il risultato più basso."}, {"roll": 27, "name": "Aliante", "en": "Glider", "text": "Mentre cadete, potete marcare uno Stress per aprire questo piccolo paracadute e planare fino a terra sani e salvi."}, {"roll": 28, "name": "Anello del Silenzio", "en": "Ring of Silence", "text": "Spendete una Speranza per attivare questo anello. I vostri passi sono silenziosi fino al vostro prossimo riposo."}, {"roll": 29, "name": "Monile della Tranquillità", "en": "Calming Pendant", "text": "Quando dovreste marcare il vostro ultimo Stress, tirate un d6. Con un risultato di 5 o più, non lo marcate."}, {"roll": 30, "name": "Fiasca Doppia", "en": "Dual Flask", "text": "Questa fiasca può contenere due liquidi diversi. Potete passare dall'uno all'altro azionando una piccola levetta sul fianco della fiasca."}, {"roll": 31, "name": "Borsa della Sabbia Volubile", "en": "Bag of Ficklesand", "text": "Superando un Tiro Presenza (10), potete convincere questo sacchetto di sabbia a diventare molto più pesante o più leggero. Inoltre, superando un Tiro Astuzia (10), potete soffiare un po' di sabbia in faccia a un bersaglio per renderlo temporaneamente Vulnerabile."}, {"roll": 32, "name": "Anello della Resistenza", "en": "Ring of Resistance", "text": "Una volta per riposo lungo, potete attivare questo anello dopo un attacco riuscito contro di voi per dimezzarne i danni."}, {"roll": 33, "name": "Piuma di Fenice", "en": "Phoenix Feather", "text": "Se avete con voi almeno una Piuma di Fenice quando perdete i sensi, ottenete un bonus di +1 al tiro che determina se ricevete una cicatrice."}, {"roll": 34, "name": "Scatola delle Tante Cose", "en": "Box of Many Goods", "text": "Una volta per riposo lungo, potete aprire questa piccola scatola e tirare un d12. Con un risultato di 1-6, è vuota. Con un risultato di 7-10, contiene un consumabile comune casuale. Con un risultato di 11-12, contiene due consumabili comuni casuali."}, {"roll": 35, "name": "Ninnolo della Lama di Vento", "en": "Airblade Charm", "text": "Potete fissare questo ninnolo a un'arma con portata Mischia. Tre volte per riposo, potete attivarlo e attaccare un bersaglio entro distanza Ravvicinata."}, {"roll": 36, "name": "Seme del Portale", "en": "Portal Seed", "text": "Potete piantare questo seme nel terreno per far crescere un portale in quel punto. Il portale è pronto all'uso dopo 24 ore. Potete usarlo per viaggiare verso qualunque altro luogo in cui abbiate piantato un seme del portale. Un portale può essere distrutto infliggendogli una qualsiasi quantità di danni magici."}, {"roll": 37, "name": "Catenina della Meditazione", "en": "Paragon’s Chain", "text": "Come mossa da interludio, potete meditare su un ideale o un principio a cui tenete e concentrare la vostra volontà in questa catenina. Una volta per riposo lungo, potete spendere una Speranza per tirare un d20 come Dado Speranza nei tiri direttamente in linea con quel principio."}, {"roll": 38, "name": "Amuleto dell'Elusione", "en": "Elusive Amulet", "text": "Una volta per riposo lungo, potete attivare questo amuleto per diventare Nascosti finché non vi muovete. Mentre siete Nascosti in questo modo, restate invisibili anche se un avversario si sposta in un punto da cui normalmente vi vedrebbe."}, {"roll": 39, "name": "Medaglione della Speranza", "en": "Hopekeeper Locket", "text": "Durante un riposo lungo, se avete 6 Speranza, potete spendere una Speranza per infondere in questo medaglione la vostra ferma determinazione. Quando avete 0 Speranza, potete usare il medaglione per ottenere immediatamente una Speranza. Il medaglione deve essere infuso di nuovo prima di poter essere usato ancora in questo modo."}, {"roll": 40, "name": "Sacca Infinita", "en": "Infinite Bag", "text": "Gli oggetti che riponete in questa sacca vengono conservati in una dimensione tascabile che non esaurisce mai lo spazio. Potete recuperare un oggetto in qualsiasi momento."}, {"roll": 41, "name": "Reliquia del Viaggiatore", "en": "Stride Relic", "text": "Ottenete un bonus di +1 alla vostra Agilità. Potete portare con voi una sola reliquia."}, {"roll": 42, "name": "Reliquia di Possanza", "en": "Bolster Relic", "text": "Ottenete un bonus di +1 alla vostra Forza. Potete portare con voi una sola reliquia."}, {"roll": 43, "name": "Reliquia del Sangue Freddo", "en": "Control Relic", "text": "Ottenete un bonus di +1 alla vostra Astuzia. Potete portare con voi una sola reliquia."}, {"roll": 44, "name": "Reliquia dell'Armonia", "en": "Attune Relic", "text": "Ottenete un bonus di +1 al vostro Istinto. Potete portare con voi una sola reliquia."}, {"roll": 45, "name": "Reliquia del Fascino", "en": "Charm Relic", "text": "Ottenete un bonus di +1 alla vostra Presenza. Potete portare con voi una sola reliquia."}, {"roll": 46, "name": "Reliquia dell'Illuminazione", "en": "Enlighten Relic", "text": "Ottenete un bonus di +1 alla vostra Conoscenza. Potete portare con voi una sola reliquia."}, {"roll": 47, "name": "Reliquia dell'Introspezione", "en": "Honing Relic", "text": "Ottenete un bonus di +1 a un'Esperienza a vostra scelta. Potete portare con voi una sola reliquia."}, {"roll": 48, "name": "Pendente di Scintillante", "en": "Flickerfly Pendant", "text": "Finché portate questo pendente, le vostre armi con portata Mischia che infliggono danni fisici acquisiscono un velo iridescente e possono attaccare bersagli entro distanza Prossima."}, {"roll": 49, "name": "Stivali della Traversata", "en": "Lakestrider Boots", "text": "Potete camminare sulla superficie dell'acqua come se fosse terreno soffice."}, {"roll": 50, "name": "Compagno d'Argilla", "en": "Clay Companion", "text": "Quando modellate questa palla d'argilla dandole la forma di un compagno animale, questa si comporta come quell'animale. Per esempio, un ragno d'argilla può tessere ragnatele d'argilla, mentre un uccello d'argilla può volare. Il compagno d'argilla conserva memoria e identità tra una forma e l'altra, ma può adottare nuovi atteggiamenti a ogni forma."}, {"roll": 51, "name": "Formula della Polvere Mistica", "en": "Mythic Dust Recipe", "text": "Come mossa da interludio, potete usare una manciata di finissima polvere d'oro per preparare una Polvere Mistica."}, {"roll": 52, "name": "Frammento di Memoria", "en": "Shard of Memory", "text": "Una volta per riposo lungo, potete spendere 2 Speranza per richiamare una carta dominio dalla vostra riserva invece di pagarne il Costo di Richiamo."}, {"roll": 53, "name": "Gemma dell'Alacrità", "en": "Gem of Alacrity", "text": "Potete incastonare questa gemma in un'arma, così da poter usare la vostra Agilità quando attaccate con quell'arma."}, {"roll": 54, "name": "Gemma della Potenza", "en": "Gem of Might", "text": "Potete incastonare questa gemma in un'arma, così da poter usare la vostra Forza quando attaccate con quell'arma."}, {"roll": 55, "name": "Gemma della Precisione", "en": "Gem of Precision", "text": "Potete incastonare questa gemma in un'arma, così da poter usare la vostra Astuzia quando attaccate con quell'arma."}, {"roll": 56, "name": "Gemma dell'Intuizione", "en": "Gem of Insight", "text": "Potete incastonare questa gemma in un'arma, così da poter usare il vostro Istinto quando attaccate con quell'arma."}, {"roll": 57, "name": "Gemma dell'Audacia", "en": "Gem of Audacity", "text": "Potete incastonare questa gemma in un'arma, così da poter usare la vostra Presenza quando attaccate con quell'arma."}, {"roll": 58, "name": "Gemma della Sagacia", "en": "Gem of Sagacity", "text": "Potete incastonare questa gemma in un'arma, così da poter usare la vostra Conoscenza quando attaccate con quell'arma."}, {"roll": 59, "name": "Anello della Risolutezza Inflessibile", "en": "Ring of Unbreakable Resolve", "text": "Una volta per sessione, quando il GM spende una Paura, potete spendere 4 Speranza per annullare gli effetti di quella Paura."}, {"roll": 60, "name": "Cintura dell'Unità", "en": "Belt of Unity", "text": "Una volta per sessione, potete spendere 5 Speranza per guidare un Tiro Combinato con tre PG invece di due."}], "consumabili": [{"roll": 1, "name": "Pozione del Viaggiatore", "en": "Stride Potion", "text": "Ottenete un bonus di +1 al vostro prossimo Tiro Agilità."}, {"roll": 2, "name": "Pozione della Possanza", "en": "Bolster Potion", "text": "Ottenete un bonus di +1 al vostro prossimo Tiro Forza."}, {"roll": 3, "name": "Pozione del Sangue Freddo", "en": "Control Potion", "text": "Ottenete un bonus di +1 al vostro prossimo Tiro Astuzia."}, {"roll": 4, "name": "Pozione di Armonia", "en": "Attune Potion", "text": "Ottenete un bonus di +1 al vostro prossimo Tiro Istinto."}, {"roll": 5, "name": "Pozione di Fascino", "en": "Charm Potion", "text": "Ottenete un bonus di +1 al vostro prossimo Tiro Presenza."}, {"roll": 6, "name": "Pozione dell'Illuminazione", "en": "Enlighten Potion", "text": "Ottenete un bonus di +1 al vostro prossimo Tiro Conoscenza."}, {"roll": 7, "name": "Pozione di Guarigione Minore", "en": "Minor Health Potion", "text": "Rimuovete 1d4 PF."}, {"roll": 8, "name": "Pozione di Recupero Minore", "en": "Minor Stamina Potion", "text": "Rimuovete 1d4 Stress."}, {"roll": 9, "name": "Veleno di Macinadenti", "en": "Grindletooth Venom", "text": "Potete applicare questo veleno a un'arma che infligge danni fisici per aggiungere un d6 al vostro prossimo tiro danni con quell'arma."}, {"roll": 10, "name": "Foglie di Varik", "en": "Varik Leaves", "text": "Potete mangiare queste foglie appaiate per ottenere immediatamente 2 Speranza."}, {"roll": 11, "name": "Fiala di Goccia Lunare", "en": "Vial of Moondrip", "text": "Quando bevete il contenuto di questa fiala, potete vedere nell'oscurità totale fino al vostro prossimo riposo."}, {"roll": 12, "name": "Frammento Arcano Instabile", "en": "Unstable Arcane Shard", "text": "Potete effettuare un Tiro Astuzia per lanciare questo frammento contro un gruppo di avversari entro distanza Lontana. I bersagli contro cui avete successo subiscono 1d20 danni magici."}, {"roll": 13, "name": "Pozione di Costanza", "en": "Potion of Stability", "text": "Potete bere questa pozione per scegliere una mossa da interludio aggiuntiva."}, {"roll": 14, "name": "Veleno di Macinadenti Potenziato", "en": "Improved Grindletooth Venom", "text": "Potete applicare questo veleno a un'arma che infligge danni fisici per aggiungere un d8 al vostro prossimo tiro danni con quell'arma."}, {"roll": 15, "name": "Maschera d'Argilla", "en": "Morphing Clay", "text": "Potete spendere una Speranza per usare quest'argilla e alterare il vostro volto quanto basta a rendervi irriconoscibili fino al vostro prossimo riposo."}, {"roll": 16, "name": "Fiala di Nerofumo", "en": "Vial of Darksmoke", "text": "Quando un avversario vi attacca, usate questa fiala e tirate un numero di d6 pari alla vostra Agilità. Aggiungete il risultato più alto alla vostra Evasione contro quell'attacco."}, {"roll": 17, "name": "Radice Balzante", "en": "Jumping Root", "text": "Mangiate questa radice per balzare una volta fino a distanza Lontana senza dover tirare."}, {"roll": 18, "name": "Polvere Cauterizzante", "en": "Snap Powder", "text": "Marcate uno Stress e rimuovete un PF."}, {"roll": 19, "name": "Pozione di Guarigione", "en": "Health Potion", "text": "Rimuovete 1d4+1 PF."}, {"roll": 20, "name": "Pozione di Recupero", "en": "Stamina Potion", "text": "Rimuovete 1d4+1 Stress."}, {"roll": 21, "name": "Ricambi per Armature", "en": "Armor Stitcher", "text": "Potete usare questi ricambi per spendere un numero qualsiasi di Speranza e rimuovere altrettante Caselle Armatura."}, {"roll": 22, "name": "Balsamo delle Branchie", "en": "Gill Salve", "text": "Potete spalmare questo balsamo sul collo per respirare sott'acqua per un numero di minuti pari al vostro livello."}, {"roll": 23, "name": "Pergamena di Copiatura", "en": "Replication Parchment", "text": "Toccando un'altra pergamena con questa, potete copiarne perfettamente il contenuto. Una volta usata, questa pergamena diventa carta comune."}, {"roll": 24, "name": "Frammento Arcano Migliorato", "en": "Improved Arcane Shard", "text": "Potete effettuare un Tiro Astuzia per lanciare questo frammento contro un gruppo di avversari entro distanza Lontana. I bersagli contro cui avete successo subiscono 2d20 danni magici."}, {"roll": 25, "name": "Pozione del Viaggiatore Maggiore", "en": "Major Stride Potion", "text": "Ottenete un bonus di +1 alla vostra Agilità fino al vostro prossimo riposo."}, {"roll": 26, "name": "Pozione della Possanza Maggiore", "en": "Major Bolster Potion", "text": "Ottenete un bonus di +1 alla vostra Forza fino al vostro prossimo riposo."}, {"roll": 27, "name": "Pozione del Sangue Freddo Maggiore", "en": "Major Control Potion", "text": "Ottenete un bonus di +1 alla vostra Astuzia fino al vostro prossimo riposo."}, {"roll": 28, "name": "Pozione di Armonia Maggiore", "en": "Major Attune Potion", "text": "Ottenete un bonus di +1 al vostro Istinto fino al vostro prossimo riposo."}, {"roll": 29, "name": "Pozione di Fascino Maggiore", "en": "Major Charm Potion", "text": "Ottenete un bonus di +1 alla vostra Presenza fino al vostro prossimo riposo."}, {"roll": 30, "name": "Pozione dell'Illuminazione Maggiore", "en": "Major Enlighten Potion", "text": "Ottenete un bonus di +1 alla vostra Conoscenza fino al vostro prossimo riposo."}, {"roll": 31, "name": "Sangue di Yorgi", "en": "Blood of the Yorgi", "text": "Potete bere questo sangue per scomparire dal punto in cui vi trovate e riapparire immediatamente in un punto che potete vedere entro distanza Remota."}, {"roll": 32, "name": "Filtro Segreto di Homet", "en": "Homet's Secret Potion", "text": "Dopo aver bevuto questa pozione, il vostro prossimo attacco riuscito è un successo critico."}, {"roll": 33, "name": "Saliva di Spinarossa", "en": "Redthorn Saliva", "text": "Potete applicare questa saliva a un'arma che infligge danni fisici per aggiungere un d12 al vostro prossimo tiro danni con quell'arma."}, {"roll": 34, "name": "Pietra Incanalatrice", "en": "Channelstone", "text": "Potete usare questa pietra per prendere un incantesimo o un grimorio dalla vostra riserva, usarlo una volta e rimetterlo nella riserva."}, {"roll": 35, "name": "Polvere Mistica", "en": "Mythic Dust", "text": "Potete applicare questa polvere a un'arma che infligge danni magici per aggiungere un d12 al vostro prossimo tiro danni con quell'arma."}, {"roll": 36, "name": "Pasta Acida", "en": "Acidpaste", "text": "Questa pasta corrode muri e altre superfici in lampi di luce accecante."}, {"roll": 37, "name": "Fiaccola di Speranza", "en": "Hopehold Flare", "text": "Quando usate questa fiaccola, gli alleati entro distanza Ravvicinata tirano un d6 quando spendono una Speranza. Con un risultato di 6, ottengono l'effetto di quella Speranza senza spenderla. La fiaccola dura fino alla fine della scena."}, {"roll": 38, "name": "Frammento Arcano Maggiore", "en": "Major Arcane Shard", "text": "Potete effettuare un Tiro Astuzia per lanciare questo frammento contro un gruppo di avversari entro distanza Lontana. I bersagli contro cui avete successo subiscono 4d20 danni magici."}, {"roll": 39, "name": "Ossocavo", "en": "Featherbone", "text": "Potete usare questo osso per controllare la velocità della vostra caduta per un numero di minuti pari al vostro livello."}, {"roll": 40, "name": "Cerchio del Vuoto", "en": "Circle of the Void", "text": "Marcate uno Stress per creare un vuoto che si estende fino a distanza Lontana. All'interno del vuoto non è possibile lanciare magie e le creature al suo interno sono immuni ai danni magici."}, {"roll": 41, "name": "Linfa dell'Albero del Sole", "en": "Sun Tree Sap", "text": "Consumate questa linfa per tirare un d6. Con un risultato di 5-6, rimuovete 2 PF. Con un risultato di 2-4, rimuovete 3 Stress. Con un risultato di 1, vedete oltre il velo della morte e tornate cambiati, ricevendo una cicatrice."}, {"roll": 42, "name": "Veleno di Zanna Sgocciolante", "en": "Dripfang Poison", "text": "Una creatura che ingerisce questo veleno subisce 8d10 danni magici diretti."}, {"roll": 43, "name": "Pozione di Guarigione Maggiore", "en": "Major Health Potion", "text": "Rimuovete 1d4+2 PF."}, {"roll": 44, "name": "Pozione di Recupero Maggiore", "en": "Major Stamina Potion", "text": "Rimuovete 1d4+2 Stress."}, {"roll": 45, "name": "Fragranza d'Ogre", "en": "Ogre Musk", "text": "Potete usare questa fragranza per impedire a chiunque di seguire le vostre tracce con mezzi ordinari o magici fino al vostro prossimo riposo."}, {"roll": 46, "name": "Germoglio d'Ali", "en": "Wingsprout", "text": "Vi spuntano ali magiche che vi permettono di volare per un numero di minuti pari al vostro livello."}, {"roll": 47, "name": "Giara delle Voci Perdute", "en": "Jar of Lost Voices", "text": "Potete aprire questa giara per liberare un'eco assordante di voci per un numero di minuti pari al vostro Istinto. Le creature entro distanza Lontana impreparate al suono subiscono 6d8 danni magici."}, {"roll": 48, "name": "Infusione di Fior di Drago", "en": "Dragonbloom Tea", "text": "Potete bere questa infusione per scatenare un soffio infuocato. Effettuate un Tiro Istinto contro tutti gli avversari davanti a voi entro distanza Ravvicinata. I bersagli contro cui avete successo subiscono 2d20 danni fisici usando la vostra Competenza."}, {"roll": 49, "name": "Noce di Pontile", "en": "Bridge Seed", "text": "Spesse liane crescono dalla vostra posizione fino a un punto a vostra scelta entro distanza Lontana, permettendovi di arrampicarvi su di esse o di attraversarle. Le liane si dissolvono al vostro prossimo riposo."}, {"roll": 50, "name": "Linfa del Sonno", "en": "Sleeping Sap", "text": "Potete bere questa pozione per addormentarvi e godere di una notte intera di riposo. Al risveglio rimuovete tutto lo Stress."}, {"roll": 51, "name": "Banchetto di Xuria", "en": "Feast of Xuria", "text": "Potete mangiare questo pasto per rimuovere tutti i PF e lo Stress e ottenere 1d4 Speranza."}, {"roll": 52, "name": "Miele Incollante", "en": "Bonding Honey", "text": "Questo miele può essere usato per incollare permanentemente due oggetti."}, {"roll": 53, "name": "Pozione di Rimpicciolimento", "en": "Shrinking Potion", "text": "Potete bere questa pozione per dimezzare la vostra taglia finché non decidete di abbandonare questa forma o fino al vostro prossimo riposo. In questa forma, avete un bonus di +2 all'Agilità e una penalità di -1 alla Competenza."}, {"roll": 54, "name": "Pozione della Crescita", "en": "Growing Potion", "text": "Potete bere questa pozione per raddoppiare la vostra taglia finché non decidete di abbandonare questa forma o fino al vostro prossimo riposo. In questa forma, avete un bonus di +2 alla Forza e un bonus di +1 alla Competenza."}, {"roll": 55, "name": "Pietra della Conoscenza", "en": "Knowledge Stone", "text": "Se morite mentre stringete questa pietra, un alleato può prendere una carta dalla vostra dotazione e metterla nella propria dotazione o riserva. Dopo che ha preso questa conoscenza, la pietra si sbriciola."}, {"roll": 56, "name": "Muschio Dolce", "en": "Sweet Moss", "text": "Potete consumare questo muschio durante un riposo per rimuovere 1d10 PF o 1d10 Stress."}, {"roll": 57, "name": "Sfera Accecante", "en": "Blinding Orb", "text": "Potete attivare questa sfera per creare un lampo di luce accecante. Tutti i bersagli entro distanza Ravvicinata diventano Vulnerabili finché non marcano PF."}, {"roll": 58, "name": "Infuso Mortale", "en": "Death Tea", "text": "Dopo aver bevuto questo infuso, uccidete all'istante il vostro bersaglio quando ottenete un successo critico in un attacco. Se non ottenete un successo critico in un attacco prima del vostro prossimo riposo lungo, morite."}, {"roll": 59, "name": "Specchio di Calendula", "en": "Mirror of Marigold", "text": "Quando subite danni, potete spendere una Speranza per annullarli; dopodiché lo specchio va in frantumi."}, {"roll": 60, "name": "Lacrima di Stelle", "en": "Stardrop", "text": "Potete usare questa lacrima di stelle per evocare una pioggia di comete che infligge 8d20 danni fisici a tutti i bersagli entro distanza Remota."}]};

// Tabella aggiuntiva dello SRD 2.0 (nomi italiani non ufficiali)
window.GEN.loot.oggetti2 = [{"roll": 1, "name": "Triboli", "en": "Caltrops", "text": "Potete spargere questi triboli in un'area Prossima attorno a voi. Una creatura che attraversa l'area di corsa deve marcare uno Stress."}, {"roll": 2, "name": "Rampino", "en": "Grapnel", "text": "Avete vantaggio ai tiri azione per scalare pareti a strapiombo."}, {"roll": 3, "name": "Biglie d'Acciaio", "en": "Ball Bearings", "text": "Questo sacchetto contiene sfere di metallo perfettamente lisce."}, {"roll": 4, "name": "Tabacchiera di Polvere di Drago", "en": "Box of Dragon Dust", "text": "Questa tabacchiera è piena di una polvere che prende fuoco facilmente."}, {"roll": 5, "name": "Anello del Nottambulo", "en": "Nighthawker's Ring", "text": "Spendete una Speranza per attivare la gemma di questo anello fino alla fine della scena. Finché è attiva, la gemma cambia colore per indicare quanto chi la indossa è vicino a un tesoro nascosto: colori caldi se è vicino, freddi se è lontano."}, {"roll": 6, "name": "Cannocchiale Elfico", "en": "Elven Spyglass", "text": "Potete usare questo cannocchiale per ingrandire la vista di cento volte."}, {"roll": 7, "name": "Granuli del Buongustaio", "en": "Gourmet Granules", "text": "Questa polvere saporita rende delizioso e sano qualsiasi cibo su cui viene cosparsa, per quanto insipido o marcio sia."}, {"roll": 8, "name": "Pertica Pieghevole", "en": "Collapsible Pole", "text": "Potete smontare questa pertica di circa 5,5 metri in sei segmenti da 90 centimetri che si incastrano tra loro."}, {"roll": 9, "name": "Penna d'Alanera", "en": "Blackwing Quill", "text": "Questa penna da scrittura non finisce mai l'inchiostro e non va mai temperata."}, {"roll": 10, "name": "Coltello Pieghevole di Silee", "en": "Silee's Folding Knife", "text": "Questa lama di 7 centimetri taglia con facilità qualsiasi cosa, tranne il manico in cui si richiude."}, {"roll": 11, "name": "Giocattolo a Molla", "en": "Windup Toy", "text": "Questo piccolo congegno meccanico ha la forma di un cucciolo di lupo-strige e si può programmare per eseguire semplici trucchi."}, {"roll": 12, "name": "Dadi Truccati", "en": "Loaded Dice", "text": "Con un Tiro Astuzia (14) riuscito potete scegliere il risultato di questi dadi appesantiti. Se tirate con Paura, chiunque stia guardando capisce che i dadi sono truccati."}, {"roll": 13, "name": "Corno di Cavascorza", "en": "Hollowbark Horn", "text": "Potete suonare questo corno per chiamare una piccola creatura del bosco che svolga un compito semplice."}, {"roll": 14, "name": "Corda che si Annoda", "en": "Self-Tying Rope", "text": "Potete ordinare a questa corda di annodarsi o sciogliersi da sola."}, {"roll": 15, "name": "Bussola del Ladro", "en": "Thief's Compass", "text": "Al chiuso questa bussola indica l'uscita più vicina; all'aperto, l'ingresso più vicino."}, {"roll": 16, "name": "Campanella del Viandante", "en": "Traveler's Bell", "text": "Una volta per riposo lungo, potete suonare questa campanella per aprire magicamente, per un'ora, il sentiero sicuro più breve attraverso un terreno impervio."}, {"roll": 17, "name": "Torcia di Mandragora", "en": "Mandragorian Torch", "text": "Questa torcia emette una luce che solo chi la impugna può vedere."}, {"roll": 18, "name": "Stivali della Morbida Mistica", "en": "Boots of Supple Mystique", "text": "Finché indossate questi stivali non lasciate tracce né impronte."}, {"roll": 19, "name": "Barattolo di Zefiro", "en": "Zephyr's Jar", "text": "Durante il maltempo potete aprire questo barattolo vuoto per catturare la tempesta e lasciare il cielo sereno. La tempesta resta dentro finché non riaprite il barattolo per liberarla."}, {"roll": 20, "name": "Anello del Ritorno", "en": "Returning Ring", "text": "Quando lanciate la vostra arma primaria mentre indossate questo anello, l'arma vi ricompare in mano subito dopo l'attacco."}, {"roll": 21, "name": "Rete del Martin Pescatore", "en": "Kingfisher's Net", "text": "Una volta per riposo lungo, potete usare questa rete per tirare fuori un pesce vivo da qualsiasi specchio d'acqua, per quanto improbabile sia che ci siano pesci."}, {"roll": 22, "name": "Cintura del Titano", "en": "Titan's Girdle", "text": "Una volta per scena, potete attivare questa cintura per ottenere un bonus di +1 alla Competenza per il vostro prossimo attacco."}, {"roll": 23, "name": "Velo di Ferro", "en": "Iron Veil", "text": "Questo copricapo di maglia rende chi lo indossa invisibile alle creature fatate."}, {"roll": 24, "name": "Sacca dei Batuffoli", "en": "Furball Bag", "text": "Una volta per riposo, potete tirare fuori da questa sacca 2d20 creature pelose e innocue, grandi come gatti, di origine e specie indefinibili."}, {"roll": 25, "name": "Cavigliera del Passo Sussurrato", "en": "Whisperstep Anklet", "text": "Questa cavigliera rende silenziosi i vostri passi, purché non vi muoviate più in fretta del passo normale."}, {"roll": 26, "name": "Lente dell'Incantatore", "en": "Enchanter's Loupe", "text": "Potete usare questa lente per vedere attraverso illusioni e incantamenti."}, {"roll": 27, "name": "Sfera Specchiata di Escher", "en": "Escher's Mirrorball", "text": "Una volta per riposo lungo, potete ordinare a questa sfera d'argento, grande come un pugno, di catturare sulla sua superficie un'immagine a tutto tondo di ciò che la circonda. L'immagine dura fino al vostro prossimo riposo lungo."}, {"roll": 28, "name": "Moneta del Baro", "en": "Cheater's Coin", "text": "Quando lanciate questa moneta, potete spendere una Speranza per decidere su quale faccia cade."}, {"roll": 29, "name": "Campana del Guardiano delle Tombe", "en": "Gravewarden's Bell", "text": "Questa campana suona quando un fantasma o una creatura non morta si muove entro distanza Lontana."}, {"roll": 30, "name": "Reliquiario del Santo Cieco", "en": "Reliquary of the Sightless Saint", "text": "Ottenete un bonus di +1 al Dado Speranza quando scegliete la mossa finale Rischiare Tutto."}, {"roll": 31, "name": "Mappa della Rivelazione", "en": "Map of Revelation", "text": "Potete sintonizzare questa mappa su una creatura alla volta. La mappa mostra sempre dove si trova quella creatura."}, {"roll": 32, "name": "Lastra d'Ossidiana di Dagginae", "en": "Dagginae's Obsidian Slate", "text": "Gli archivisti usano questa lastra di vetro vulcanico, sottile come un'ostia, per prendere appunti. Ciò che vi si incide scompare, ma si può richiamare con una parola di comando che scegliete voi."}, {"roll": 33, "name": "Zaino di Gadiman", "en": "Gadiman's Backpack", "text": "Una volta per riposo, potete spendere una Speranza per far comparire dentro questo zaino un oggetto comune grande al massimo come una scatola di 30 centimetri di lato."}, {"roll": 34, "name": "Moneta dell'Eclissi", "en": "Eclipse Coin", "text": "Una volta per riposo, lanciate una moneta. Con testa ottenete un bonus di +1 ai tiri attacco fino al vostro prossimo attacco riuscito. Con croce ottenete +1 all'Evasione finché un attacco contro di voi non fallisce."}, {"roll": 35, "name": "Cappello dello Stregone", "en": "Sorcerer's Hat", "text": "Questo cappello blu a cono è coperto di stelle d'argento. Una volta per riposo, potete lanciare un incantesimo di una carta nella vostra riserva con un Costo di Richiamo pari o inferiore al vostro rango. Non funziona con le carte messe in riserva in modo permanente."}, {"roll": 36, "name": "Guanti di Pelle di Ghoul", "en": "Ghoulskin Gloves", "text": "Quando attaccate con un'arma fisica mentre indossate questi guanti, il danno conta sia come fisico sia come magico."}, {"roll": 37, "name": "Guanti della Prontezza", "en": "Gloves of Alacrity", "text": "Quando dovreste marcare uno Stress per ricaricare un'arma, non lo marcate."}, {"roll": 38, "name": "Amuleto dell'Insonne", "en": "Insomniac's Periapt", "text": "Quando fate un riposo senza rimuovere Punti Ferita né Stress, ottenete un bonus di +2 ai tiri attacco e ai tiri danni fino al vostro prossimo riposo."}, {"roll": 39, "name": "Sella del Cavaliere Selvaggio", "en": "Wildrider's Saddle", "text": "Qualsiasi animale su cui viene fissata questa sella capisce i comandi di chi lo cavalca."}, {"roll": 40, "name": "Diademi delle Anime Gemelle", "en": "Soul-Twin Circlets", "text": "Due creature possono indossare questa coppia di diademi. Potete spendere una Speranza per scambiarvi di posto con chi indossa l'altro diadema."}, {"roll": 41, "name": "Oracolo del Nominatore", "en": "Namer's Oracle", "text": "Una volta per sessione, potete tirare questi dadi runici per scoprire il nome completo dell'ultima persona che avete toccato."}, {"roll": 42, "name": "Occhiali del Crogiolo", "en": "Crucible Frames", "text": "Questi occhiali rivelano i punti deboli di oggetti e creature. Tre volte per riposo, potete spendere una Speranza per avere vantaggio a un tiro attacco."}, {"roll": 43, "name": "Spilla dell'Egida Bifronte", "en": "Two-Faced Aegis Brooch", "text": "Una volta per riposo, lanciate una moneta. Con testa diventate immuni al prossimo danno fisico che subite. Con croce diventate immuni al prossimo danno magico che subite."}, {"roll": 44, "name": "Bracciali del Contraccolpo", "en": "Knockback Bracelets", "text": "Quando un vostro attacco con un'arma va a segno, potete spingere il bersaglio fino a distanza Ravvicinata dalla sua posizione."}, {"roll": 45, "name": "Disco di Forza", "en": "Force Disc", "text": "Questo disco piatto e scintillante di forza magica ha un diametro di 1,2 metri ed è legato per magia a un sassolino. Il disco fluttua sempre 90 centimetri a nord del sassolino, alla sua stessa altezza. Il sassolino ha una massa pari a un centesimo della massa totale trasportata dal disco."}, {"roll": 46, "name": "Muffole della Talpa", "en": "Molepaw Mittens", "text": "Spendete una Speranza per nuotare nella terra come se fosse acqua per i prossimi 10 minuti."}, {"roll": 47, "name": "Pendente del Custode del Tempo", "en": "Timekeeper's Pendant", "text": "A ogni riposo potete scegliere una mossa da interludio in più."}, {"roll": 48, "name": "Pendente del Pugnale di Ferro", "en": "Iron Dagger Pendant", "text": "Una volta per riposo lungo, potete spendere una Speranza per dire al pendente il nome di una creatura. Fino al vostro prossimo riposo lungo, il pendente vi tira dolcemente verso il punto in cui si trova quella creatura."}, {"roll": 49, "name": "Collare dell'Ascesa", "en": "Collar of Ascendancy", "text": "Un animale che indossa questo collare può parlare e capire la lingua comune."}, {"roll": 50, "name": "Santuario Temporale", "en": "Temporal Sanctuary", "text": "Un PG che fa un riposo nel santuario temporale può scegliere una mossa da interludio in più."}, {"roll": 51, "name": "Elmo dell'Eroe", "en": "Hero's Helm", "text": "Quando ottenete un successo critico in un attacco, tutti gli alleati entro distanza Ravvicinata ottengono una Speranza."}, {"roll": 52, "name": "Anelli dell'Amicizia", "en": "Rings of Friendship", "text": "Due creature possono indossare questa coppia di anelli a forma di serpente arrotolato. Potete spendere la Speranza di chi indossa l'altro anello (con il suo permesso) come se fosse vostra."}, {"roll": 53, "name": "Anelli del Cameratismo", "en": "Rings of Camaraderie", "text": "Due creature possono indossare questa coppia di anelli di legno. Potete marcare lo Stress di chi indossa l'altro anello (con il suo permesso) come se fosse vostro."}, {"roll": 54, "name": "Anelli dell'Alleanza", "en": "Rings of Alliance", "text": "Due creature possono indossare questa coppia di anelli d'oro rosa. Una volta per sessione, potete avviare un Tiro Combinato con chi indossa l'altro anello senza spendere Speranza e senza che conti nel limite di Tiri Combinati della sessione."}, {"roll": 55, "name": "Diadema del Fobofago", "en": "Phobophage's Circlet", "text": "Quando il GM spende una Paura, tirate un d4. Una volta per scena, con un 4 rimuovete uno Stress."}, {"roll": 56, "name": "Scialle d'Aculei", "en": "Quillshawl", "text": "Se un avversario vi attacca entro distanza di Mischia, deve superare un Tiro Reazione (12) o marcare un Punto Ferita."}, {"roll": 57, "name": "Pendente della Distorsione", "en": "Warp Pendant", "text": "Una volta per riposo, marcate uno Stress per teletrasportarvi in un luogo che vedete chiaramente."}, {"roll": 58, "name": "Cornici Portale", "en": "Portal Frames", "text": "Questa coppia di piccole cornici decorate, una rossa e una blu, è collegata: tutto ciò che entra in una esce dall'altra."}, {"roll": 59, "name": "Reliquia della Comunione", "en": "Communion Relic", "text": "Una volta per riposo, potete spendere una Speranza per usare un'Esperienza di un alleato come se fosse vostra. Potete portare con voi una sola reliquia."}, {"roll": 60, "name": "Reliquia dell'Augure", "en": "Augur's Relic", "text": "Una volta per riposo lungo, potete attivare il vostro Privilegio della Speranza senza spendere Speranza. Potete portare con voi una sola reliquia."}];
window.GEN.loot.consumabili2 = [{"roll": 1, "name": "Candela di Protezione", "en": "Warding Candle", "text": "Potete accendere questa candela per riempire un'area entro distanza Ravvicinata con un alone di luce. Una creatura fuori dall'alone non può entrarvi se ha cattive intenzioni verso qualcuno che si trova all'interno. La candela brucia per un'ora."}, {"roll": 2, "name": "Polvere Iridiana", "en": "Iridian Dust", "text": "Questa polvere multicolore si attacca a tutto e impedisce alle creature che ne sono coperte di diventare Nascoste."}, {"roll": 3, "name": "Seme Verglasiano", "en": "Verglasian Seed", "text": "Potete usare questa scheggia di ghiaccio per congelare all'istante uno specchio d'acqua fino a distanza Ravvicinata."}, {"roll": 4, "name": "Bezoar del Coppiere", "en": "Cupbearer's Bezoar", "text": "Potete inghiottire questo bezoar per diventare immuni ai veleni fino al vostro prossimo riposo lungo."}, {"roll": 5, "name": "Pozione Mantodimuschio", "en": "Mossmantle Potion", "text": "Potete bere questo infuso per mimetizzarvi perfettamente negli ambienti naturali fino al vostro prossimo riposo."}, {"roll": 6, "name": "Pastiglia dell'Uccello Lira", "en": "Lyrebird Lozenge", "text": "Potete sciogliere in bocca questa pastiglia per imitare alla perfezione qualsiasi voce abbiate sentito, fino alla fine della scena."}, {"roll": 7, "name": "Fiala di Cadipiuma", "en": "Vial of Featherfall", "text": "Potete bere questa pozione per ignorare i danni da caduta per i prossimi 10 minuti."}, {"roll": 8, "name": "Saliva di Chimera", "en": "Chimeric Saliva", "text": "Potete applicare questa saliva a un'arma che infligge danni fisici: fino al vostro prossimo riposo i suoi danni diventano magici."}, {"roll": 9, "name": "Bustina di Polvere Stellare", "en": "Packet of Space Dust", "text": "Questa polvere rende più leggero dell'aria qualsiasi cosa ricopra. Una bustina basta a coprire il contenuto di un cestino da picnic e l'effetto dura un'ora."}, {"roll": 10, "name": "Erba da Pipa", "en": "Pipeweed", "text": "Quando durante un riposo breve scegliete la mossa da interludio Rimuovere Stress, potete fumare quest'erba non inebriante per rimuovere uno Stress in più. Anche gli altri PG che hanno scelto Rimuovere Stress ottengono questo beneficio."}, {"roll": 11, "name": "Polvere del Veggente dei Morti", "en": "Deathseer's Powder", "text": "Potete cospargere questa polvere su un cadavere recente per evocare un replay spettrale del suo ultimo minuto di vita."}, {"roll": 12, "name": "Sale dell'Uccisore", "en": "Slayer's Salt", "text": "Potete spargere questo sale in una linea su davanzali o soglie per creare una barriera magica che le creature non morte non possono attraversare finché la linea non viene interrotta."}, {"roll": 13, "name": "Latte di Yakamelo", "en": "Yakamel Milk", "text": "Dopo aver bevuto questo latte, la prossima volta che rimuovete 1 o più Punti Ferita ne rimuovete uno in più."}, {"roll": 14, "name": "Fungo Luminoso", "en": "Glowmoss Mushroom", "text": "Potete spezzare questo fungo: i pezzi brillano di un blu intenso fino al vostro prossimo riposo lungo."}, {"roll": 15, "name": "Olio di Melma Rossa", "en": "Red Ooze Oil", "text": "Potete ungere la vostra arma con quest'olio. Il prossimo attacco riuscito con quell'arma infligge 1d8 danni magici aggiuntivi e rende il bersaglio temporaneamente Infiammato. Finché è Infiammato, il bersaglio subisce 1d4 danni magici quando diventa protagonista."}, {"roll": 16, "name": "Accampamento Istantaneo", "en": "Instant Camp", "text": "Potete aprire questa piccola scatola meccanica: diventa una tenda abbastanza grande da ospitare al sicuro sei persone. La tenda si richiude alla fine del vostro prossimo riposo lungo."}, {"roll": 17, "name": "Mazzetto di Zampe di Ragno", "en": "Bundle of Spiderlegs", "text": "Potete mangiare queste zampe di ragno per camminare sui muri fino al vostro prossimo riposo."}, {"roll": 18, "name": "Bottiglia di Nebbia Ciscana", "en": "Ciscan Fog Bottle", "text": "Potete rompere questa bottiglia per riempire l'area entro distanza Ravvicinata di una nebbia magica. Una creatura che entra nella nebbia rimuove uno Stress e diventa Nascosta."}, {"roll": 19, "name": "Seme di Spinascatto", "en": "Snapthorn Seed", "text": "Potete lanciare questo seme verso un punto che vedete. Esplode in un groviglio di rampicanti che rende temporaneamente Trattenute tutte le creature entro distanza Ravvicinata da quel punto."}, {"roll": 20, "name": "Bottiglia del Folletto", "en": "Sprite Bottle", "text": "Quando marcate il vostro ultimo Punto Ferita, questa bottiglia va in frantumi e libera il folletto che contiene. Il folletto rimuove tutti i vostri Punti Ferita, poi svanisce dal Regno Mortale."}, {"roll": 21, "name": "Bomba Gravitazionale", "en": "Gravity Bomb", "text": "Potete lanciare questa sfera meccanica, grande come una pesca, verso un punto entro distanza Lontana. Implode e trascina fino a distanza di Mischia da sé tutte le creature e gli oggetti entro distanza Ravvicinata da quel punto."}, {"roll": 22, "name": "Fiore Pettegolo", "en": "Gossip Flower", "text": "Potete piantare questo seme nella terra. Cresce all'istante in un fiorellino che registra tutto ciò che sente, fino a una settimana. Quando lo cogliete, il fiore ripete ciò che ha registrato in tempo reale, poi appassisce."}, {"roll": 23, "name": "Gettone dello Sdoppiamento", "en": "Displacement Token", "text": "Potete inghiottire questo gettone per evocare due illusioni di voi stessi che potete controllare. Ogni illusione dura finché non subisce danni o fino al vostro prossimo riposo."}, {"roll": 24, "name": "Polvere della Strega Notturna", "en": "Night Hag's Dust", "text": "Potete soffiare questa polvere in faccia a un avversario per impedirgli di rimuovere Stress fino al vostro prossimo riposo lungo."}, {"roll": 25, "name": "Filo che si Cuce da Sé", "en": "Self-Sewing Thread", "text": "Potete usare questo filo per rimuovere un Punto Ferita oppure 2 Caselle Armatura."}, {"roll": 26, "name": "Fortuna del Muratore", "en": "Stonemason's Fortune", "text": "Quando gettate a terra questo mattone grigio, cresce all'istante in un muro di pietra massiccia alto 1,8 metri, largo 3 e spesso 60 centimetri."}, {"roll": 27, "name": "Pozione Mnemonica", "en": "Mnemonic Potion", "text": "Potete bere questa pozione per Utilizzare un'Esperienza senza spendere Speranza."}, {"roll": 28, "name": "Unguento di Salamandra", "en": "Salamander Salve", "text": "Potete spalmarvi questo unguento sulla pelle per diventare immuni al calore fino al vostro prossimo riposo."}, {"roll": 29, "name": "Olio di Melma Verde", "en": "Green Ooze Oil", "text": "Potete ungere la vostra arma con quest'olio. Il prossimo attacco riuscito con quell'arma infligge 1d8 danni magici aggiuntivi e rende il bersaglio temporaneamente Corroso. Finché è Corroso, il bersaglio subisce una penalità di -2 alle soglie di danno."}, {"roll": 30, "name": "Globo di Luce Solare", "en": "Sunlight Orb", "text": "Potete frantumare questo globo per far sembrare l'area entro distanza Remota illuminata dal sole di giorno per le prossime 24 ore."}, {"roll": 31, "name": "Globo di Luce Lunare", "en": "Moonlight Orb", "text": "Potete frantumare questo globo per far sembrare l'area entro distanza Remota una notte rischiarata dalla luna per le prossime 24 ore."}, {"roll": 32, "name": "Fiasca di Mida", "en": "Midas Flask", "text": "Potete versare questa fiaschetta di liquido alchemico su un oggetto comune per trasformarlo all'istante in una manciata d'oro."}, {"roll": 33, "name": "Bastone dell'Inversione", "en": "Staff of Reversal", "text": "Potete spezzare questo bastone a terra per annullare una trasformazione o un effetto magico entro distanza Lontana."}, {"roll": 34, "name": "Intruglio del Berserker", "en": "Berserker's Brew", "text": "Quando bevete questo sorso di liquido ottenete un bonus a Forza e una penalità ad Astuzia e Conoscenza pari al vostro Istinto (minimo 1). L'effetto dura finché non scegliete una mossa finale o fino al vostro prossimo riposo."}, {"roll": 35, "name": "Scheggia di Braciolite", "en": "Emberite Shard", "text": "Scegliete un punto entro distanza Lontana. Tutti i bersagli entro distanza Ravvicinata da quel punto devono superare un Tiro Reazione (16) o subire 3d6 danni magici e diventare temporaneamente In Fiamme. Una creatura In Fiamme tira un d4 ogni volta che effettua un tiro azione: con 1 marca un Punto Ferita, con 4 si libera della condizione In Fiamme."}, {"roll": 36, "name": "Scheggia di Articite", "en": "Arcticite Shard", "text": "Scegliete un punto entro distanza Lontana. Tutti i bersagli entro distanza Ravvicinata da quel punto devono superare un Tiro Reazione (16) o subire 3d6 danni magici e diventare temporaneamente Trattenuti dal ghiaccio."}, {"roll": 37, "name": "Scheggia di Folgorite", "en": "Fulgurite Shard", "text": "Scegliete un punto entro distanza Lontana. Tutti i bersagli entro distanza Ravvicinata da quel punto devono superare un Tiro Reazione (16) o subire 3d6 danni magici e marcare 1d4 Stress, mentre i fulmini crepitano nell'area."}, {"roll": 38, "name": "Pozione del Demiurgo", "en": "Demiurge's Draught", "text": "Potete bere questa pozione per ottenere un bonus di +1 alla Competenza per il vostro prossimo tiro attacco riuscito."}, {"roll": 39, "name": "Tè d'Artiglio di Gallo", "en": "Cockerel Claw Tea", "text": "Potete bere questo tè per ricaricare i vostri privilegi come se aveste fatto un riposo lungo."}, {"roll": 40, "name": "Pozione della Vigilanza", "en": "Potion of Vigilance", "text": "Potete bere questa pozione per ottenere un bonus di +1 all'Evasione finché non marcate un Punto Ferita."}, {"roll": 41, "name": "Intruglio Cacofonico", "en": "Cacophonous Concoction", "text": "Quando bevete questa pozione, nessun testimone riesce a raccontare ciò che dite o fate nell'ora successiva: ogni tentativo di riferire ciò che ha visto, sentito o percepito esce confuso o senza senso."}, {"roll": 42, "name": "Idromele degli Incubi", "en": "Nightmare Mead", "text": "Potete bere questa pozione per scoprire la paura più profonda della prossima persona che guardate negli occhi. Quando lo fate, il GM ottiene una Paura."}, {"roll": 43, "name": "Paletto dell'Abiura", "en": "Stake of Abjuration", "text": "Potete piantare questo paletto nel terreno e pronunciare un proclama. Fino al vostro prossimo riposo, una creatura entro distanza Lontana dal paletto che trasgredisce il proclama deve marcare uno Stress. Al vostro prossimo riposo il paletto va in pezzi."}, {"roll": 44, "name": "Sudario dello Psicopompo", "en": "Psychopomp's Shroud", "text": "Potete stendere questo sudario sul cadavere di una creatura morta da poco. Il suo spirito entra nel sudario e diventa il vostro assistente spettrale fino all'alba successiva, quando varca il velo della morte portando con sé il sudario."}, {"roll": 45, "name": "Ampolla d'Inchiostro Abissale", "en": "Phial of Deep Ink", "text": "Potete bere questa bottiglietta d'inchiostro per trasformarvi per un'ora in un cefalopode grande più o meno come voi. Ottenete pelle gommosa, ossa morbide, la capacità di respirare sott'acqua e nuovi arti fino ad averne otto in tutto."}, {"roll": 46, "name": "Tonico del Mesmerista", "en": "Mesmer's Tonic", "text": "Quando bevete questo tonico, fino al vostro prossimo riposo l'unica cosa che sentite sono i pensieri superficiali delle creature entro distanza Prossima."}, {"roll": 47, "name": "Pozione dell'Invisibilità", "en": "Invisibility Potion", "text": "Siete Nascosti finché non infliggete danni a un'altra creatura o fino al vostro prossimo riposo."}, {"roll": 48, "name": "Siero Formoide", "en": "Formoid Serum", "text": "Potete bere questa pozione per diventare uno sciame di 16 milioni di formiche fino alla fine della scena. Conservate e potete usare tutto l'equipaggiamento, il bottino e i privilegi."}, {"roll": 49, "name": "Unguento Pelle d'Acciaio", "en": "Steelskin Salve", "text": "Potete spalmarvi questo unguento sulla pelle per ottenere, fino alla fine della scena, un bonus alle soglie di danno pari al vostro rango."}, {"roll": 50, "name": "Pomelo del Semidio", "en": "Godling's Pomelo", "text": "Potete mangiare questo agrume per rimuovere tutti i Punti Ferita e tutto lo Stress."}, {"roll": 51, "name": "Spirito di Pelle di Serpe", "en": "Snakeskin Spirit", "text": "Potete bere questa pozione per perdere lo strato esterno della pelle e guarire una cicatrice."}, {"roll": 52, "name": "Maledizione dell'Incantatore", "en": "Magic-User's Malison", "text": "Quando liberate l'anima dell'incantatore intrappolata qui, potete lanciare un incantesimo di una carta nella vostra riserva come se fosse nella vostra dotazione. Non funziona con le carte messe in riserva in modo permanente."}, {"roll": 53, "name": "Recisore Quintessenziale", "en": "Quintessential Severant", "text": "Potete usare questa lama magica per tagliare un legame magico o metafisico, come un incantamento, un contratto, un vincolo magico o un giuramento divino. Quando lo fate, la lama va in frantumi."}, {"roll": 54, "name": "Maschera del Sé Riflesso", "en": "Mask of the Echoed Self", "text": "Potete indossare questa maschera durante il vostro prossimo passaggio di livello per scambiare tra loro i valori di qualsiasi tratto. Quando lo fate, la maschera diventa per sempre il vostro volto."}, {"roll": 55, "name": "Campana del Negromante Cavaliere", "en": "Necroprancer's Bell", "text": "Potete spezzare a terra questa campana arrugginita e senza batacchio per evocare un destriero scheletrico che emerge dalla terra e vi serve fino all'alba successiva."}, {"roll": 56, "name": "Mantodrago", "en": "Drakemantle", "text": "Potete usare quest'antica pelle di drago incantata per assumere tratti draconici fino alla fine della scena, quando la pelle cade a brandelli. Fino ad allora potete volare e ottenete un bonus di +5 alle soglie di danno e un bonus di +1 alla Competenza."}, {"roll": 57, "name": "Fallacia del Giocatore", "en": "Gambler's Fallacy", "text": "Potete spendere quante manciate d'oro volete infilandole in questo salvadanaio di ceramica a forma di maialino. Quando lo lanciate verso un punto entro distanza Lontana, esplode e infligge 1d20 danni magici per ogni manciata d'oro spesa a tutte le creature entro distanza Ravvicinata da quel punto. Tutto l'oro nel salvadanaio va distrutto."}, {"roll": 58, "name": "Tonico Cuor di Leone", "en": "Lionheart Tonic", "text": "Potete bere questo tonico per ottenere un bonus di +1 alla Competenza finché non tirate con Paura."}, {"roll": 59, "name": "Lacrime dell'Eroe Immortale", "en": "Tears of the Undying Hero", "text": "Quando bevete questa pozione, la morte non può toccarvi fino al vostro prossimo riposo lungo. Quando dovreste marcare il vostro ultimo Punto Ferita, invece di scegliere una mossa finale effettuate un ultimo tiro azione, poi cadete in un sonno senza sogni finché un alleato non sceglie la mossa da interludio Curare Ferite per rimuovere i vostri Punti Ferita."}, {"roll": 60, "name": "Pozione Passo di Piuma", "en": "Featherstep Potion", "text": "Potete bere questa pozione per far spuntare dalle caviglie piccole ali che vi danno un bonus all'Evasione pari al vostro rango, fino al vostro prossimo riposo."}];

